def run(**kwargs):
    import hashlib, random, hmac
    samples = [(1788541232, 175835), (1788629052, 417354), (1788633149, 353291), (1788637020, 269854), (1788637075, 395651)]
    email = "vfdeals01@uberip.com"
    hits = []
    def check(name, fn):
        try:
            if all(fn(t) == c for t, c in samples):
                hits.append(name)
                return True
        except Exception:
            pass
        return False
    tforms = [("t", lambda t: str(t)), ("t-1", lambda t: str(t-1)), ("t+1", lambda t: str(t+1)),
              ("t//60", lambda t: str(t//60)), ("t//600", lambda t: str(t//600)), ("t//3600", lambda t: str(t//3600))]
    for hname, h in [("md5", hashlib.md5), ("sha1", hashlib.sha1), ("sha256", hashlib.sha256)]:
        for tname, tf in tforms:
            for mode, mod, off in [("mod1e6", 10**6, 0), ("mod9e5+1e5", 9*10**5, 10**5)]:
                def fn(t, h=h, tf=tf, mod=mod, off=off):
                    return int(h(tf(t).encode()).hexdigest(), 16) % mod + off
                check(f"{hname}({tname}) {mode}", fn)
            def fn6(t, h=h, tf=tf):
                d = h(tf(t).encode()).hexdigest()
                return int(d[:6], 16) % 10**6
            check(f"{hname}({tname}) first6hex", fn6)
            def fnl6(t, h=h, tf=tf):
                d = h(tf(t).encode()).hexdigest()
                return int(d[-6:], 16) % 10**6
            check(f"{hname}({tname}) last6hex", fnl6)
        # email-mixed variants
        for tname, tf in tforms[:3]:
            for mixname, mix in [("em+t", lambda e, s: e + s), ("t+em", lambda e, s: s + e), ("em:t", lambda e, s: e + ":" + s)]:
                def fnm(t, h=h, tf=tf, mix=mix):
                    return int(h(mix(email, tf(t)).encode()).hexdigest(), 16) % 10**6
                check(f"{hname}({mixname}({tname})) mod1e6", fnm)
    # HMAC with weak keys
    for key in ["duskyr", "secret", "otp", "duskyr.com", "no-reply@duskyr.com", "vfdeals01@uberip.com"]:
        for hname, h in [("md5", hashlib.md5), ("sha256", hashlib.sha256)]:
            def fnh(t, key=key, h=h):
                return int(hmac.new(key.encode(), str(t).encode(), h).hexdigest(), 16) % 10**6
            check(f"hmac_{hname}('{key}')", fnh)
    # Python Mersenne seeded by time
    seeds = [("t", lambda t: t), ("t//60", lambda t: t//60), ("t//600", lambda t: t//600)]
    for sname, sf in seeds:
        for ri in range(4):
            def fnr(t, sf=sf, ri=ri):
                random.seed(sf(t))
                for _ in range(ri):
                    random.random()
                return random.randint(0, 999999)
            check(f"pyrandom.seed({sname}).randint(0,999999) skip{ri}", fnr)
            def fnr2(t, sf=sf, ri=ri):
                random.seed(sf(t))
                for _ in range(ri):
                    random.random()
                return random.randint(100000, 999999)
            check(f"pyrandom.seed({sname}).randint(1e5,999999) skip{ri}", fnr2)
            def fnr3(t, sf=sf, ri=ri):
                random.seed(sf(t))
                for _ in range(ri):
                    random.random()
                return int(random.random() * 1000000)
            check(f"pyrandom.seed({sname}).random()*1e6 skip{ri}", fnr3)
    # LCG chain search: does next code follow prev code under classic LCG params within 200k steps
    lcg_params = [("glibc", 1103515245, 12345, 2**31), ("java", 25214903917, 11, 2**48), ("musl", 6364136223846793005, 1, 2**64), ("mmix", 6364136223846793005, 1442695040888963407, 2**64)]
    chain_hits = []
    for name, a, c, m in lcg_params:
        for i in range(len(samples) - 1):
            prev = samples[i][1]; nxt = samples[i+1][1]
            state = prev
            found = None
            for k in range(1, 200001):
                state = (a * state + c) % m
                v = state % 10**6
                if v == nxt or (v % 900000 + 100000) == nxt:
                    found = k
                    break
            if found:
                chain_hits.append(f"{name}:pair{i}->{i+1}@step{found}")
    # delta structure: code vs t linear fit residual check (is code anywhere near affine in t?)
    ts = [s[0] for s in samples]; cs = [s[1] for s in samples]
    n = len(ts)
    mt = sum(ts)/n; mc = sum(cs)/n
    denom = sum((t-mt)**2 for t in ts)
    slope = sum((t-mt)*(c-mc) for t, c in samples)/denom if denom else 0
    intercept = mc - slope*mt
    resid = max(abs(c - (slope*t + intercept)) for t, c in samples)
    verdict = "PREDICTABLE" if hits or chain_hits else "STRONG-ENTROPY (secrets-class likely)"
    out = {
        "verdict": verdict,
        "deterministic_hits": hits,
        "lcg_chain_hits": chain_hits,
        "linear_fit": {"slope_per_s": round(slope, 6), "max_residual": round(resid, 1), "note": "residual >> 450000 => non-affine"},
        "samples": samples,
    }
    return str(out)

