def run(**kwargs):
    import json, re, base64, os, glob
    path = kwargs.get("path", "")
    pattern = kwargs.get("pattern", "api/")
    if not path:
        cands = sorted(glob.glob("missions/duskyr.com/extractions/*data_extract.json"), key=os.path.getmtime)
        if not cands:
            return "no extraction files found"
        path = cands[-1]
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        raw = f.read()
    # the extraction JSON wraps the HTML in a "text" field; work on the raw text either way
    html = raw
    m = re.search(r'"text":\s*"(.*?)",\s*"tail"', raw, re.S)
    if m:
        html = m.group(1).encode().decode("unicode_escape", errors="replace")
    out = {"file": path, "html_len": len(html)}
    # pull bundler manifest + template script tags
    blocks = re.findall(r'<script type="__bundler/(\w+)">(.*?)</script>', html, re.S)
    out["bundler_blocks"] = [b[0] for b in blocks]
    decoded_chunks = []
    for kind, body in blocks:
        body = body.strip()
        try:
            obj = json.loads(body)
        except Exception:
            # maybe it's already the payload text
            decoded_chunks.append((kind, body))
            continue
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(v, str) and len(v) > 200:
                    try:
                        decoded_chunks.append((f"{kind}:{k}", base64.b64decode(v + "=" * (-len(v) % 4)).decode("utf-8", "replace")))
                    except Exception:
                        decoded_chunks.append((f"{kind}:{k}", v))
                elif isinstance(v, dict):
                    for k2, v2 in v.items():
                        if isinstance(v2, str) and len(v2) > 200:
                            try:
                                decoded_chunks.append((f"{kind}:{k}.{k2}", base64.b64decode(v2 + "=" * (-len(v2) % 4)).decode("utf-8", "replace")))
                            except Exception:
                                decoded_chunks.append((f"{kind}:{k}.{k2}", v2))
        elif isinstance(obj, str) and len(obj) > 200:
            try:
                decoded_chunks.append((kind, base64.b64decode(obj + "=" * (-len(obj) % 4)).decode("utf-8", "replace")))
            except Exception:
                decoded_chunks.append((kind, obj))
    out["decoded_chunks"] = len(decoded_chunks)
    # scan decoded content for grammar
    hits = {}
    rx = re.compile(re.escape(pattern) + r"[A-Za-z0-9_/\-]*")
    interesting_rx = re.compile(r"(signup|register|verify|vetstore|admin|buy|topup|redeem|confirm|otp|auth|secret|token|webhook)", re.I)
    for name, text in decoded_chunks:
        found = rx.findall(text)
        for fnd in set(found):
            hits.setdefault(fnd, []).append(name)
        for im in interesting_rx.finditer(text):
            ctx = text[max(0, im.start() - 60):im.start() + 80].replace("\n", " ")
            hits.setdefault("CTX:" + im.group(0).lower(), []).append(ctx[:140])
    out["hits"] = {k: v[:4] for k, v in sorted(hits.items())[:60]}
    out["n_hits"] = len(hits)
    return str(out)

